    'admin_smtp_setup_host_port_where'        => 'V cPaneli otvorte Email Accounts → Manage → Connect Devices → Mail Client Manual Settings a skopírujte názov hostiteľa SMTP, režim SSL/TLS a port; u iných poskytovateľov použite príslušnú obrazovku odosielajúcej pošty (Google Workspace Admin, Microsoft 365, Plesk atď.).',
    'admin_smtp_setup_host_port_errors'       => 'Nesprávny hostiteľ, port alebo šifrovanie spôsobia chyby TLS handshake, hlášky „Could not connect to SMTP host“ alebo tiché timeouty pri odoslaní.',
    'admin_smtp_setup_host_port_examples'     => 'Príklad shared hostingu: dizzyscripts.com (SSL, port 465). Ďalšie možnosti: smtp.gmail.com (STARTTLS, port 587), email-smtp.eu-west-1.amazonaws.com (TLS, port 587).',
    'admin_smtp_setup_host_port_security'     => 'Preferujte šifrované porty, overte zhodu certifikátu s hostiteľom a vyhnite sa nešifrovanému portu 25, aby ste predišli odchyteniu poverení.',
    'admin_smtp_setup_auth_title'             => 'Autentifikácia a heslá aplikácií',
    'admin_smtp_setup_auth_desc'              => 'Poverenia dokazujú, že schránka povoľuje tejto aplikácii odosielať poštu.',
    'admin_smtp_setup_auth_where'             => 'V cPaneli použite Email Accounts → Manage na skopírovanie používateľského mena SMTP (celá schránka) a na vygenerovanie alebo reset hesla; rovnaký krok urobte v Google Workspace, Microsoft 365 alebo inom paneli.',
    'admin_smtp_setup_auth_errors'            => 'Nesprávne údaje alebo nesúlad adresy From vyvolajú chyby 535/534 a zabránia odoslaniu správ.',
    'admin_smtp_setup_auth_examples'          => 'Použite úplnú adresu schránky (napr. creatorpulse@dizzyscripts.com) a zadajte ju aj do poľa From; služby ako Google Workspace či Outlook 365 často vyžadujú heslá aplikácií.',
    'admin_smtp_setup_auth_security'          => 'Heslo uchovávajte bezpečne, pravidelne ho obmieňajte, zapnite 2FA a nepoužívajte SMTP údaje na iné prihlásenia.',
    'admin_smtp_setup_spf_dkim_title'         => 'Overenie domény (SPF & DKIM)',
    'admin_smtp_setup_spf_dkim_desc'          => 'Záznamy SPF a DKIM umožňujú prijímacím serverom overiť, že tento SMTP hostiteľ smie posielať poštu vašej domény.',
    'admin_smtp_setup_spf_dkim_where'         => 'Publikujte hodnoty SPF/DKIM u svojho DNS hostiteľa (Cloudflare, Route53, cPanel Zone Editor) podľa údajov poskytovateľa pošty.',
    'admin_smtp_setup_spf_dkim_errors'        => 'Chýbajúce alebo nesprávne záznamy vedú k „SPF fail“ alebo „DKIM none“, čo môže presunúť legitímne správy do spamu alebo ich odmietnuť.',
    'admin_smtp_setup_spf_dkim_examples'      => 'Príklad SPF: v=spf1 include:_spf.google.com ~all. Príklad DKIM: google._domainkey.yourdomain.com s verejným kľúčom z Google Workspace.',
    'admin_smtp_setup_spf_dkim_security'      => 'Po publikovaní overte záznamy pomocou MXToolbox alebo Google Postmaster a sledujte DMARC reporty, aby ste včas odhalili spoofing.',
    'admin_smtp_setup_test_title'             => 'Testovanie a monitoring doručiteľnosti',
    'admin_smtp_setup_test_desc'              => 'Pravidelné testy potvrdia celý poštový tok – poverenia, TLS aj smerovanie – ešte predtým, než sa naň spoliehajú zákazníci.',
    'admin_smtp_setup_test_where'             => 'Použite tlačidlo „Send Test Email“ na tejto stránke alebo nástroje CLI (swaks, openssl s_client) a odošlite správu do monitorovanej schránky.',
    'admin_smtp_setup_test_errors'            => 'Sledujte SMTP kódy ako 454 TLS not available alebo 550 relay denied, aby ste zistili, ktorá časť procesu zlyhala.',
    'admin_smtp_setup_test_examples'          => 'Odosielajte testy do podpornej schránky aj na externé adresy (Gmail/Outlook), aby ste skontrolovali hlavičky a umiestnenie v spame.',
